const a=JSON.parse('{"workId":"zhuangzi","chapter":{"id":"zhuangzi_ch-1","workId":"zhuangzi","order":1,"title":"逍遙遊第一","difficulty":4,"estimatedMinutes":10,"passageIds":["zhuangzi_ch-1_p-1","zhuangzi_ch-1_p-2","zhuangzi_ch-1_p-3","zhuangzi_ch-1_p-4","zhuangzi_ch-1_p-5","zhuangzi_ch-1_p-6","zhuangzi_ch-1_p-7","zhuangzi_ch-1_p-8","zhuangzi_ch-1_p-9","zhuangzi_ch-1_p-10","zhuangzi_ch-1_p-11","zhuangzi_ch-1_p-12","zhuangzi_ch-1_p-13","zhuangzi_ch-1_p-14","zhuangzi_ch-1_p-15","zhuangzi_ch-1_p-16","zhuangzi_ch-1_p-17","zhuangzi_ch-1_p-18","zhuangzi_ch-1_p-19","zhuangzi_ch-1_p-20","zhuangzi_ch-1_p-21","zhuangzi_ch-1_p-22","zhuangzi_ch-1_p-23","zhuangzi_ch-1_p-24","zhuangzi_ch-1_p-25","zhuangzi_ch-1_p-26","zhuangzi_ch-1_p-27","zhuangzi_ch-1_p-28","zhuangzi_ch-1_p-29","zhuangzi_ch-1_p-30","zhuangzi_ch-1_p-31"],"tags":[]},"passages":[{"id":"zhuangzi_ch-1_p-1","chapterId":"zhuangzi_ch-1","order":1,"canonicalText":"北冥有魚，其名為鯤。鯤之大，不知其幾千里也。化而為鳥，其名為鵬。鵬之背，不知其幾千里也；怒而飛，其翼若垂天之雲。是鳥也，海運則將徙於南冥。南冥者，天池也。","sentenceIds":["zhuangzi_ch-1_p-1_s-1","zhuangzi_ch-1_p-1_s-2","zhuangzi_ch-1_p-1_s-3","zhuangzi_ch-1_p-1_s-4","zhuangzi_ch-1_p-1_s-5","zhuangzi_ch-1_p-1_s-6","zhuangzi_ch-1_p-1_s-7"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"北海有一條魚，它的名字叫作「鯤」。鯤的龐大，不知道有幾千里。它變化為鳥，名字叫作「鵬」。大鵬的脊背，不知道有幾千里長；當它奮起振翅高飛時，張開的翅膀就像垂掛在天際的雲彩。這隻大鵬，當海水動盪洶湧之時，就要遷徙飛往南海。南海，就是天然的大池。","analysis":"【主旨】〈逍遙遊〉以宏大奇詭的寓言開篇，借「鯤化為鵬」與「徙於南冥」的意象，展現突破形體拘限、由潛沉而奮飛的生命超越氣象。\\n【詞義】「冥」通「溟」，幽遠的大海；「鯤」本為微小之魚卵，莊子極反其意以喻極大；「怒」指鼓足力量、奮起振翼；「垂天之雲」形容雙翼展開遮蔽天際；「海運」指大海動盪、海風大作之時；「天池」指天然形成的浩瀚大池。\\n【章法】由「魚」至「鳥」，由「北冥」至「南冥」，由「潛游」至「奮飛」，空間視野在極短篇幅內拉升至無窮之境，筆勢奇崛超拔，奠定全篇汪洋恣肆的浪漫基調。\\n【思想】鯤鵬由深海微隱化為九天巨翼，既象徵生命對世俗狹隘境界的脫胎換骨與精神騰飛，同時也為下文揭示「鵬猶有所待」（受制於風）埋下辯證伏筆。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-2","chapterId":"zhuangzi_ch-1","order":2,"canonicalText":"齊諧者，志怪者也。曰：「鵬之徙於南冥也，水擊三千里，摶扶搖而上者九萬裏，去以六月息者也。」野馬也，塵埃也，生物之以息相吹也。","sentenceIds":["zhuangzi_ch-1_p-2_s-1","zhuangzi_ch-1_p-2_s-2","zhuangzi_ch-1_p-2_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"《齊諧》這本書，是一部專門記載怪異事物的書。書中記載說：「大鵬遷徙到南海時，翅膀在水面上激起三千里的浪花，盤旋乘著旋風直上九萬里高空，飛離北海後要乘著六個月的大風才能停息。」春天林野間奔騰浮動的霧氣、空中飛揚飄散的塵埃，都是天地間生物用氣息相互吹動而產生的。","analysis":"【主旨】引古籍《齊諧》之記載佐證大鵬高飛之巨力，並以野馬塵埃對照大鵬，揭示天地萬物無論大小，皆在氣息流轉中相互依託。\\n【詞義】「齊諧」人名或齊國記錄怪異之書；「志怪」記載奇特怪異之事；「水擊」翅膀拍擊水面；「摶」盤旋環繞；「扶搖」由下而上之旋風；「去以六月息」指飛行憑藉半年的大風氣流；「野馬」春日曠野上游動蒸騰的遊氣；「塵埃」揚塵浮沫；「息」氣息、大風。\\n【章法】先引書證強化寓言的真實感與歷史厚度，隨即將視線由九萬里之鵬突降至微細之塵埃遊氣，形成「極大」與「極微」的劇烈張力。\\n【思想】莊子在此暗示：不論大如摶扶搖之大鵬，抑或微如飄蕩之塵埃，只要未能超越條件的牽引，本質上皆是「有所待」的受拘存在。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-3","chapterId":"zhuangzi_ch-1","order":3,"canonicalText":"天之蒼蒼，其正色邪？其遠而無所至極邪？其視下也，亦若是則已矣。","sentenceIds":["zhuangzi_ch-1_p-3_s-1","zhuangzi_ch-1_p-3_s-2","zhuangzi_ch-1_p-3_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"天空那一片蒼茫深藍，難道是它本來的顏色嗎？還是因為天色太高遠而看不到邊際盡頭呢？大鵬從九萬里高空往下俯瞰人間，所見到的景象大概也正如我們抬頭看天一樣吧！","analysis":"【主旨】以仰望蒼天的視覺經驗質疑感官認知之客觀性，藉大鵬高空俯瞰的視角轉換，破除人類自我中心的觀察侷限。\\n【詞義】「蒼蒼」深青色、蒼茫之色；「正色」天之本色、真實之色；「至極」終點、極限；「視下」從高空俯視大地；「若是」像這樣。\\n【章法】連用兩個反問句（「其……邪？其……邪？」）引導讀者懷疑既定視覺印象，再以「其視下也，亦若是則已矣」作換位推想，視角在天地上下之間雙向流轉。\\n【思想】此處展現莊子深刻的相對主義認識論：人在地面看天呈蒼蒼之色，鵬在天際看地亦呈蒼蒼之象。認知往往由觀察者所處之位置與距離決定，世間並無絕對孤立的客觀視角。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-4","chapterId":"zhuangzi_ch-1","order":4,"canonicalText":"且夫水之積也不厚，則負大舟也無力。覆杯水於坳堂之上，則芥為之舟；置杯焉則膠，水淺而舟大也。風之積也不厚，則其負大翼也無力。故九萬裏，則風斯在下矣，而後乃今培風；背負青天，而莫之夭閼者，而後乃今將圖南。","sentenceIds":["zhuangzi_ch-1_p-4_s-1","zhuangzi_ch-1_p-4_s-2","zhuangzi_ch-1_p-4_s-3","zhuangzi_ch-1_p-4_s-4","zhuangzi_ch-1_p-4_s-5","zhuangzi_ch-1_p-4_s-6"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"再說，如果水聚集得不夠深厚，就沒有承載大船的力量。倒一杯水在堂前低窪凹陷處，一根小草芥便能當作船隻漂浮；但如果把杯子放進去，杯底就會黏滯在泥地上，這是因為水太淺而船隻太大的緣故。風聚積得不夠厚實，那麼它托負巨大的羽翼就沒有力量。所以大鵬飛到九萬里的高空，狂風便完全聚積在它的下方，然後它才能憑藉厚積之風力滑翔；背負著無垠青天，沒有任何阻礙遏止它的去路，然後才在此時立志飛向南海。","analysis":"【主旨】以水厚載大舟與風厚負大翼為喻，深刻闡明「大器」必備「厚積」的自然法理，揭示大鵬遠圖背後所仰賴的實力與蓄積。\\n【詞義】「坳堂」堂前地面凹陷低窪處；「芥」小草；「膠」著地黏滯不前；「培風」憑藉、乘託風力；「夭閼」夭折阻礙、遏阻；「圖南」立志圖謀南飛。\\n【章法】運用精巧的層遞與類比法：先以生活常見之「坳堂杯水」設喻，由淺入深推及九萬里高空之巨風與大鵬，推理嚴密自然。\\n【思想】世人多欽羨大鵬摶扶搖之高遠，莊子卻清醒指出其必受制於「風積之厚薄」。這不僅是物理動力的生動描寫，更隱喻凡欲成就弘大精神境界者，必須具備深厚之修養與精神蓄積。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-5","chapterId":"zhuangzi_ch-1","order":5,"canonicalText":"蜩與學鳩笑之曰：「我決起而飛，槍榆枋，時則不至，而控於地而已矣，奚以之九萬裏而南為？」適莽蒼者，三湌而反，腹猶果然；適百里者，宿舂糧；適千里者，三月聚糧。之二蟲又何知！","sentenceIds":["zhuangzi_ch-1_p-5_s-1","zhuangzi_ch-1_p-5_s-2","zhuangzi_ch-1_p-5_s-3","zhuangzi_ch-1_p-5_s-4","zhuangzi_ch-1_p-5_s-5"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"蟬與小鳩鳥譏笑大鵬說：「我們奮力騰起而飛，碰到榆樹、檀樹的枝枒就停下來，有時飛不到，落在地上也就是了，何必一定要升上九萬里高空再飛往南海呢？」到近郊田野去的人，只要帶齊三餐當天返回，肚子還是飽飽的；到百里之外去的人，前一天晚上就要舂米準備乾糧；前往千里之遙的人，必須提前三個月籌備積聚糧食。這兩隻微小的小蟲小鳥又哪裡懂得大鵬的遠大志向呢！","analysis":"【主旨】透過斥鴳、蜩鳩等小動物對大鵬的嘲笑，展示狹隘經驗對高遠境界的無知與妄評，引出「行遠者必備深厚資糧」之深省。\\n【詞義】「蜩」蟬；「學鳩」小鳩雀；「決起」迅急奮飛貌；「槍」碰觸、投向；「榆枋」榆樹與枋樹；「控」投落、墜地；「適」前往；「莽蒼」郊外草木蒼翠的原野；「果然」飽足飽滿貌；「宿舂糧」隔夜舂米備糧；「之二蟲」這兩種小生物。\\n【章法】以寓言對白開場，摹寫蜩鳩自我滿足之神態栩栩如生；繼之以「莽蒼、百里、千里」三層行路備糧的長度對比，層層推進，最後以感嘆句「之二蟲又何知」有力反詰收結。\\n【思想】深刻揭示「視界決定境界」的哲理。庸俗之人受限於自身窄小生活經驗，往往以己度人、嘲笑超拔之人格理想。莊子藉此批判世俗價值觀的封閉與傲慢。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-6","chapterId":"zhuangzi_ch-1","order":6,"canonicalText":"小知不及大知，小年不及大年。奚以知其然也？朝菌不知晦朔，蟪蛄不知春秋，此小年也。","sentenceIds":["zhuangzi_ch-1_p-6_s-1","zhuangzi_ch-1_p-6_s-2","zhuangzi_ch-1_p-6_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"小聰明比不上大智慧，短暫的生命比不上長久的壽命。憑什麼知道是這樣呢？朝生暮死的菌類植物不知道什麼是月初和月末，只活夏秋的寒蟬不知道什麼是一年的春季與秋季，這就是生命短暫的「小年」。","analysis":"【主旨】正式確立〈逍遙遊〉核心範疇「大小之辯」，指出認知智慧與生命壽限在時間維度上的本質差異。\\n【詞義】「小知」狹隘淺薄之智慧；「大知」博大深遠之智慧；「小年」短促之壽命或週期；「大年」長久之壽命或週期；「朝菌」早晨生長、日出即死之菌蕈；「晦朔」農曆月末為晦、月初為朔；「蟪蛄」夏生秋死之寒蟬。\\n【章法】由「小知不及大知」總提命題，隨即以設問「奚以知其然也」起筆，引「朝菌不知晦朔」「蟪蛄不知春秋」兩個極短時序之例證，文字整飭對稱。\\n【思想】個體的認知範式受限於其存在的時空廣度。生命週期越短，其宇宙圖景越窄。由此啟發人反思自身經驗之有限，不以一孔之見為天下至理。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-7","chapterId":"zhuangzi_ch-1","order":7,"canonicalText":"楚之南有冥靈者，以五百歲為春，五百歲為秋；上古有大椿者，以八千歲為春，八千歲為秋。而彭祖乃今以久特聞，眾人匹之，不亦悲乎！","sentenceIds":["zhuangzi_ch-1_p-7_s-1","zhuangzi_ch-1_p-7_s-2","zhuangzi_ch-1_p-7_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"楚國的南方有一種叫作冥靈的神木，以五百年為一個春季，五百年為一個秋季；上古時代有一種叫作大椿的巨樹，以八千年為一個春季，八千年為一個秋季。可是彭祖直到今天還以壽命長久特別聞名於世，世俗普通人都想在壽命上與他攀比，這不是太令人可悲了嗎！","analysis":"【主旨】以冥靈、大椿之悠悠天壽對照人類傳說中壽星彭祖，揭露世人汲汲於個體壽命延續之盲目攀比與悲哀。\\n【詞義】「冥靈」傳說中的神木或靈龜；「大椿」古代傳說中長壽之巨木；「彭祖」傳說壽過八百歲之先秦壽星；「特聞」特別聞名出眾；「匹」比並、攀比；「悲」可悲可憫。\\n【章法】承接上段「小年」，以五百年、八千年為春天的宏大時間尺度展開「大年」境界，隨後話鋒突轉，將世人對彭祖之盲從攀比置於浩瀚宇宙時間中對照，形成劇烈的諷刺效果。\\n【思想】在漫長的天地歲月中，人類百八十歲乃至彭祖數百年之壽，充其量亦僅如朝菌蟪蛄之於大椿。執迷於肉身之延年益壽，不如求取精神與天道大年之融合。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-8","chapterId":"zhuangzi_ch-1","order":8,"canonicalText":"湯之問棘也是已。窮髮之北有冥海者，天池也。有魚焉，其廣數千里，未有知其脩者，其名為鯤。有鳥焉，其名為鵬，背若泰山，翼若垂天之雲，","sentenceIds":["zhuangzi_ch-1_p-8_s-1","zhuangzi_ch-1_p-8_s-2","zhuangzi_ch-1_p-8_s-3","zhuangzi_ch-1_p-8_s-4"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"商湯向大夫夏棘詢問上古異聞，正是記載了這件事。在不生草木的極北不毛之地以北，有一座深黑的大海，那就是天然的大池。那裡有一條魚，它的寬度達數千里，沒有人能測量它究竟有多長，它的名字叫作鯤。那裡有一隻鳥，名字叫作鵬，它的脊背龐大猶如泰山，展開的翅膀如同垂掛在天際的雲彩，","analysis":"【主旨】引商湯與夏棘之問答，再次重述鯤鵬化變與北冥浩瀚之景，強化超驗寓言之客觀存在性與傳承依據。\\n【詞義】「湯」商朝開國君主商湯；「棘」湯時大夫名夏棘；「窮髮」不長草木的不毛之地；「冥海」幽深廣大之北溟；「脩」長度、修長。\\n【章法】在首段鯤鵬寓言後，以「重言」（借古聖先賢湯棘之問）再度複述，但字句凝練翻新（以「背若泰山」補充「不知其幾千里」），加強文意迴環之音樂美。\\n【思想】莊子善用「三言」（寓言、重言、巵言），藉先秦帝王重臣之口講述神異，意在擊碎世俗儒墨以實用歷史、常識經驗為唯一準繩的狹隘認知。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-9","chapterId":"zhuangzi_ch-1","order":9,"canonicalText":"摶扶搖羊角而上者九萬裏，絕雲氣，負青天，然後圖南，且適南冥也。","sentenceIds":["zhuangzi_ch-1_p-9_s-1"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"它乘著旋風盤旋如羊角般扶搖直上九萬里高空，穿越衝破了密集漫捲的雲氣，背負著蒼茫無垠的青天，然後立志向南奮飛，將要遷徙到遼闊的南海去。","analysis":"【主旨】生動描繪大鵬穿越大氣、直上九霄、翱翔於青天雲海之上的壯闊航程。\\n【詞義】「摶」盤旋環繞而上；「扶搖」旋風；「羊角」形如羊角盤曲之旋轉氣流；「絕雲氣」橫越、穿越穿透雲霧層；「圖南」籌謀飛往南方。\\n【章法】連續使用「絕」「負」「圖」「適」等動詞，句式凌厲而舒展，傳神再現龐然大物自低空衝破雲層升入高天之磅礴動態。\\n【思想】大鵬必須「絕雲氣，負青天」，脫離凡世雜沓喧囂之濁氣，方能開展飛往南冥之壯舉。象徵追求至道者必先超拔於世俗名利之牽絆。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-10","chapterId":"zhuangzi_ch-1","order":10,"canonicalText":"斥鴳笑之曰：「彼且奚適也？我騰躍而上，不過數仞而下，翱翔蓬蒿之間，此亦飛之至也。而彼且奚適也？」此小大之辯也。","sentenceIds":["zhuangzi_ch-1_p-10_s-1","zhuangzi_ch-1_p-10_s-2","zhuangzi_ch-1_p-10_s-3","zhuangzi_ch-1_p-10_s-4"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"小沼澤邊的小雀譏笑大鵬說：「它究竟想要飛到哪裡去呢？我用力縱身騰躍飛起，不過飛了幾仞高就落下來，在蓬蒿雜草叢中自由翱翔，這也是飛行的最高境界了啊！而它究竟打算飛到哪裡去呢？」這就是小與大之間的本質分別。","analysis":"【主旨】以斥鴳安於蓬蒿之自滿與困惑，總結首段至此的「小大之辯」，確立境界大小不可相通之定論。\\n【詞義】「斥鴳」小池澤邊之小雀、鷓鴣之屬；「奚適」去哪裡；「數仞」古代一仞約八尺，數仞為十數尺之微高；「蓬蒿」蓬草與白蒿，喻低矮草叢；「飛之至」飛翔之極致。\\n【章法】以斥鴳「彼且奚適也」前後兩次詰問形成環狀封閉感，將其自得於蓬蒿之狹隘心理描繪得淋漓盡致；末句「此小大之辯也」如千鈞巨石，斷然總攬立論。\\n【思想】「小大之辯」不僅是形體空間與時間長短的分別，更是精神容量與生命志向的根本差異。斥鴳以蓬蒿為極致，永遠無法想像九萬里外的逍遙之境。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-11","chapterId":"zhuangzi_ch-1","order":11,"canonicalText":"故夫知效一官，行比一鄉，德合一君，而徵一國者，其自視也亦若此矣。而宋榮子猶然笑之。且舉世而譽之而不加勸，舉世而非之而不加沮，","sentenceIds":["zhuangzi_ch-1_p-11_s-1","zhuangzi_ch-1_p-11_s-2","zhuangzi_ch-1_p-11_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以，那些才智足以勝任一個官職、品行足以庇護一個鄉里、德行足以迎合一位君主，而能力足以取得一國信任的人，他們自我陶醉自命不凡的神氣，也就如同斥鴳一樣罷了。而宋榮子帶著超然的微笑看待這些人。宋榮子能夠做到：全天下的人都稱讚他，他也不會因此更加起勁；全天下的人都指責非難他，他也不會因此感到沮喪頹喪，","analysis":"【主旨】將自然界「小大之辯」轉化至人類社會，批判士大夫求官保身之自鳴得意，同時推出超越世俗毀譽之思想典型宋榮子。\\n【詞義】「知」同智，才智；「效」效力、勝任；「比」合睦、團結；「德合」道德迎合君主；「徵」取信、驗證；「自視」自我估價、自命不凡；「宋榮子」戰國初宋國學者宋鈃；「猶然」從容、譏誚自得貌；「勸」勉力、奮發；「非」非難責備；「沮」沮喪餒敗。\\n【章法】四個排比句「知效一官，行比一鄉，德合一君，而徵一國」將世俗成功人士之格局迅速歸結為「亦若斥鴳」；隨後峰迴路轉，以宋榮子之「猶然笑之」破局，拔高精神維度。\\n【思想】世俗價值依賴外界官位、權力與社會評價確立自信，本質上皆是斥鴳之流。宋榮子已能獨立於「舉世毀譽」，代表了道德人格的自我覺醒與獨立意志。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-12","chapterId":"zhuangzi_ch-1","order":12,"canonicalText":"定乎內外之分，辯乎榮辱之竟斯已矣。彼其於世未數數然也。雖然，猶有未樹也。夫列子御風而行，泠然善也，旬有五日而後反。","sentenceIds":["zhuangzi_ch-1_p-12_s-1","zhuangzi_ch-1_p-12_s-2","zhuangzi_ch-1_p-12_s-3","zhuangzi_ch-1_p-12_s-4"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"他能明確劃分自己內心與外在世界的界限，辨清世俗榮耀與屈辱的真正分寸，如此而已。他在世間從未汲汲營營去追求功名富貴。雖然如此，他依然有未曾完全樹立確立的境界。列子能夠乘著長風御氣飛行，那身姿輕妙飄逸美好極了，一連飛翔十五天然後才返回人間。","analysis":"【主旨】評定宋榮子「定內外、辯榮辱」之成就在於不汲汲於世，但指出其境界猶未究竟；繼而推出能超脫形骸拘束、御風而行的列子。\\n【詞義】「內外之分」自我心靈與外在物質評價的界線；「竟」通「境」，邊界、分寸；「斯已矣」如此而已；「數數然」汲汲營營、急切追求貌；「未樹」尚未完全建立極致之自足境界；「列子」戰國道家人物列禦寇；「泠然」輕妙、清幽飄逸之貌；「旬有五日」十五天；「反」同返。\\n【章法】由褒入貶，以「雖然，猶有未樹也」作關鍵轉折，隨即引出境界遠高於宋榮子的「列子御風」，文筆虛實掩映，一層高過一層。\\n【思想】宋榮子雖能不受外物毀譽干擾，但其心仍立足於與「外物」相對待的範疇；列子則更進一步，打破了肉身行走的沈重限制，達到輕靈超脫的境界。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-13","chapterId":"zhuangzi_ch-1","order":13,"canonicalText":"彼於致福者，未數數然也。此雖免乎行，猶有所待者也。若夫乘天地之正，而御六氣之辯，以遊無窮者，彼且惡乎待哉！故曰：至人無己，神人無功，聖人無名。","sentenceIds":["zhuangzi_ch-1_p-13_s-1","zhuangzi_ch-1_p-13_s-2","zhuangzi_ch-1_p-13_s-3","zhuangzi_ch-1_p-13_s-4"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"列子對於追求福祿名利，從不急迫求取。他這樣雖然免除了雙腳奔波步行的勞苦，但依舊是有所依賴憑藉的。至於如果能夠順應大自然的常道規律，駕馭陰、陽、風、雨、晦、明這六種自然氣象的變化轉化，進而暢遊於無始無終、廣大無邊的無窮之境，那麼他還需要依賴憑藉什麼呢！所以說：至人達到超越自我執念的「無己」，神人達到順應造化無心立勛的「無功」，聖人達到超脫世俗讚譽標籤的「無名」。","analysis":"【主旨】揭示〈逍遙遊〉乃至全書哲學的最高鵠的：超越一切依附憑託（「無待」），以「至人無己，神人無功，聖人無名」作為絕對自由的至高境界。\\n【詞義】「致福」招致求取福祉；「有所待」有所依賴、有所憑藉；「乘天地之正」順應天地自然本然的法則常道；「御六氣之辯」辯同變，駕馭陰陽風雨晦明等氣象變化；「無窮」無時空邊界的精神自由之境；「至人無己」忘卻個體執念；「神人無功」不求功名勛業；「聖人無名」不求虛聲美名。\\n【章法】此段為全篇理論之極峰：從小知（蜩鳩）、世俗之仕（知效一官）、獨立之士（宋榮子）、超拔之道人（列子），層層篩汰，最後以「若夫……彼且惡乎待哉」推導出終極結論，三句箴言整齊鏗鏘，定下全書精神綱領。\\n【思想】世間凡「有所待」（大鵬待風、列子待氣），其自由皆具脆弱性與條件性。真正的逍遙在於精神主體的徹底解脫——放下自我私欲（無己）、功名事業（無功）與社會身分（無名），方能與宇宙大道同一。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-14","chapterId":"zhuangzi_ch-1","order":14,"canonicalText":"堯讓天下於許由，曰：「日月出矣，而爝火不息，其於光也，不亦難乎！時雨降矣，而猶浸灌，其於澤也，不亦勞乎！","sentenceIds":["zhuangzi_ch-1_p-14_s-1","zhuangzi_ch-1_p-14_s-2"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"唐堯要把天下禪讓給隱士許由，說道：「太陽和月亮已經升起照耀大地了，可是地上的火把火炬卻還不熄滅，它要在光亮上與日月爭輝，不是太困難了嗎！及時的甘霖大雨已經降臨滋潤萬物了，可是人們卻還在引水挑水灌溉，這對於滋潤田畝來說，不是太徒勞疲苦了嗎！","analysis":"【主旨】以堯讓天下於許由的著名寓言，藉「爝火比日月」「浸灌比時雨」的鮮明比喻，論述至德化育天下之自然無為，超越人工治理的有心干預。\\n【詞義】「堯」古聖王唐堯；「許由」上古高士、箕山隱者；「爝火」小火把、炬火；「浸灌」挑水引渠人工澆灌；「澤」恩澤、滋潤。\\n【章法】採用平行對偶的比喻結構：以「日月與爝火」「時雨與浸灌」雙重視覺意象，生動烘托出聖者順應天道之宏偉與人為造作之渺小勞頓。\\n【思想】打破儒家將「堯舜有為而治」奉為至德的傳統觀念。在道家看來，最偉大的政治治理應當如日月普照、甘霖浸潤，不居其功、不顯其痕跡；執意人為治理反成牽累。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-15","chapterId":"zhuangzi_ch-1","order":15,"canonicalText":"夫子立而天下治，而我猶屍之，吾自視缺然。請致天下。」","sentenceIds":["zhuangzi_ch-1_p-15_s-1","zhuangzi_ch-1_p-15_s-2","zhuangzi_ch-1_p-15_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"先生只要立於尊位，天下自然就能大治，而我現在卻還空佔著帝王之位，我自己看自己深感慚愧欠缺。請允許我把天下交託奉獻給您。」","analysis":"【主旨】唐堯誠懇自承政務之不足，視權位如虛器，自願讓賢天下於高士許由。\\n【詞義】「夫子」對許由之尊稱；「屍之」尸位素餐，空居神位象徵主宰而不居其功；「缺然」自感不足、若有所失之貌；「致天下」致送交付天下政權。\\n【章法】承接上段比喻，由宏大自然氣象直落到個人政治職位的謙退，言辭誠懇懇切，將古代聖王神話轉化為對權力本質的反思。\\n【思想】在儒家語境中，禪讓是仁德之極致；莊子借此公案，卻意在引出後文許由對權位的徹底蔑棄，進一步消解「天下」這座最高世俗價值的神聖性。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-16","chapterId":"zhuangzi_ch-1","order":16,"canonicalText":"許由曰：「子治天下，天下既已治也。而我猶代子，吾將為名乎？名者，實之賓也。吾將為賓乎？","sentenceIds":["zhuangzi_ch-1_p-16_s-1","zhuangzi_ch-1_p-16_s-2","zhuangzi_ch-1_p-16_s-3","zhuangzi_ch-1_p-16_s-4"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"許由回答道：「您治理天下，天下既然已經太平大治了。而我若是現在去取代您，我難道是為了圖取虛名嗎？名聲，不過是實質內容的衍生附屬物（如賓客之於主人）罷了。難道我要去扮演這個虛妄的附屬角色嗎？","analysis":"【主旨】許由斷然拒絕堯的禪讓，從「名實之辨」切入，指出名聲乃實質之附庸，表明至人不為虛名所累的清醒態度。\\n【詞義】「既已治」天下已經安定有序；「為名」追求名聲聲譽；「實之賓」名是從屬外在的，實體才是根本內在的，賓客相對於主人。\\n【章法】許由以平靜而具穿透力的反詰句展開對答：「吾將為名乎？」「吾將為賓乎？」連環追問，直擊世俗熱衷爭名爭位之虛妄核心。\\n【思想】落實首段「聖人無名」的主題。世人汲汲於權力與頭銜，往往只是為了捕捉外在之虛名；真正自足充盈的生命，既不需靠統治天下證明自身價值，更不願淪為名利體制的附庸。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-17","chapterId":"zhuangzi_ch-1","order":17,"canonicalText":"鷦鷯巢於深林，不過一枝；偃鼠飲河，不過滿腹。歸休乎君，予無所用天下為！庖人雖不治庖，尸祝不越樽俎而代之矣。」","sentenceIds":["zhuangzi_ch-1_p-17_s-1","zhuangzi_ch-1_p-17_s-2","zhuangzi_ch-1_p-17_s-3","zhuangzi_ch-1_p-17_s-4","zhuangzi_ch-1_p-17_s-5"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"鷦鷯在繁茂幽深的林海中築巢，所佔據的也不過是一根樹枝；鼴鼠在寬廣的黃河邊飲水，所喝下的也不過能填滿肚皮。請回去歇息吧，我的國君！天下對我而言毫無用處！廚師哪怕不下廚做菜，主掌祭祀的司儀也絕不會跨過酒罈案几去越俎代庖代替他做飯！」","analysis":"【主旨】藉鷦鷯築巢、鼴鼠飲河與越俎代庖之喻，宣示生命個體之需求極其微小自足，徹底回絕世俗權位天下之引誘。\\n【詞義】「鷦鷯」體態微小之鳥；「偃鼠」即鼴鼠；「滿腹」以果腹為度；「歸休」回去休息、罷休；「庖人」廚師；「尸祝」祭祀中代表神靈受祭的司儀；「樽俎」古代盛酒肉之祭器；「越樽俎而代之」越俎代庖成語之由來。\\n【章法】先以大自然中鷦鷯、鼴鼠兩組微小動物的天然知足設喻，對照天下的廣大無當；再以宗廟祭祀禮制中的各司其職為喻，收束得極具戲劇張力與辭鋒力量。\\n【思想】在物慾與權力無限擴張的社會中，莊子提出「適度自足」的生命經濟學。生命的真實所需極為有限，天下之廣反而只會成為心靈沉重的枷鎖與異化之源。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-18","chapterId":"zhuangzi_ch-1","order":18,"canonicalText":"肩吾問於連叔曰：「吾聞言於接輿，大而無當，往而不反。吾驚怖其言，猶河漢而無極也；大有逕庭，不近人情焉。」","sentenceIds":["zhuangzi_ch-1_p-18_s-1","zhuangzi_ch-1_p-18_s-2","zhuangzi_ch-1_p-18_s-3","zhuangzi_ch-1_p-18_s-4"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"肩吾向連叔請教道：「我聽狂人接輿發表言論，話說得極其宏大卻無處著落，言辭汪洋漫衍而無所收檢。我被他的言論深深驚嚇，就像仰望銀河浩瀚看不到邊際一樣；他的話與常理相去甚遠，完全不切近普通人世的情理啊。」","analysis":"【主旨】借肩吾與連叔的對話，呈現世俗常人面對超驗道家話語時的震驚、疑懼與排斥，引出藐姑射山神人的神聖意象。\\n【詞義】「肩吾」「連叔」皆莊子寓言中之道家問答人物；「接輿」楚狂人接輿；「大而無當」宏大而漫無邊際，不合實用；「往而不反」放言高論一去不回；「河漢而無極」如天河般浩大無垠；「逕庭」門外之道與堂前之庭，成語「大相徑庭」出處，喻差距極遠；「不近人情」不合世俗常情。\\n【章法】以困惑者的主觀感受「驚怖」入筆，連下「大而無當」「往而不反」「河漢無極」「大有逕庭」四組形容，極力鋪陳接輿言論之超邁玄奇與不可思議。\\n【思想】世俗常情以實用、經驗與常識為邊界，一旦遭遇超越維度的哲學洞見，往往斥之為荒誕不經。莊子藉此反襯人類認知的自我封閉。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-19","chapterId":"zhuangzi_ch-1","order":19,"canonicalText":"連叔曰：「其言謂何哉？」","sentenceIds":["zhuangzi_ch-1_p-19_s-1","zhuangzi_ch-1_p-19_s-2"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"連叔問道：「他究竟說了些什麼呢？」","analysis":"【主旨】以極簡短的詰問轉換對話節奏，促使肩吾由主觀的情緒宣洩轉入客觀事實的陳述，引導出接輿口中藐姑射山神人的具體形象。\\n【詞義】「其言」指楚狂人接輿所發表的超驗言論；「謂何」即說了些什麼、具體內容為何。「謂」此處作言說、談論解。\\n【章法】在肩吾大肆鋪陳「大而無當」「驚怖河漢」等強烈情緒之後，連叔以四字平靜之問「其言謂何哉」截住其波瀾，形成由虛入實、引而不發的關鍵樞紐。\\n【思想】在面對超越既定經驗範疇的新思想時，真正的智者不急於憑主觀好惡妄下斷語或盲目排斥，而是首先探究其核心義理。這種冷靜審慎的理性態度，展現出探求宇宙大道時必不可少的開放心靈。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-20","chapterId":"zhuangzi_ch-1","order":20,"canonicalText":"曰：「藐姑射之山，有神人居焉，肌膚若冰雪，淖約若處子。不食五穀，吸風飲露。乘雲氣，御飛龍，而遊乎四海之外。其神凝，使物不疵癘而年穀熟，吾以是狂而不信也。」","sentenceIds":["zhuangzi_ch-1_p-20_s-1","zhuangzi_ch-1_p-20_s-2","zhuangzi_ch-1_p-20_s-3","zhuangzi_ch-1_p-20_s-4","zhuangzi_ch-1_p-20_s-5"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"肩吾回答說：「接輿說：在那遙遠的藐姑射山上，住著超凡脫俗的神人，肌膚瑩白如冰雪，體態柔美曼妙猶如待嫁的處女。他不吃人間五穀雜糧，吸飲清風朝露。駕乘著繚繞雲氣，驅馭著矯健飛龍，遨遊於四海六合之外。他的心神專一凝聚，就能使萬物免受瘟疫病害，讓天下五穀莊稼年年豐熟豐收。我認為這全是狂妄荒誕之談，所以根本不敢相信。」","analysis":"【主旨】透過接輿之口，描摹藐姑射山「神人」冰清玉潔、超凡入聖、出入太虛的至高形象，呈現道家心性解脫後的精神化境。\\n【詞義】「藐姑射之山」傳說中縹緲遙遠之神山；「淖約」通綽約，柔美婉約貌；「處子」處女、未嫁之少女；「吸風飲露」超脫人間煙火飲食；「乘雲御龍」超越大地重力與空間拘限；「神凝」心神專一虛靜、神氣凝結；「疵癘」疾病、災害。\\n【章法】文字清麗超拔，以「冰雪」「處子」繪其形神之純淨，以「雲氣」「飛龍」顯其遊歷之高遠，以「物不疵癘」「年穀熟」現其感化之盛德，末以肩吾之「狂而不信」作反襯結尾。\\n【思想】「神人」並非迷信中的神仙鬼怪，而是莊子理想化人格之文學象徵。不食五穀喻超脫物質慾望之束縛，神凝物熟喻當心靈達到虛靜極致時，自然具有安定萬物、化育天地的精神力量。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-21","chapterId":"zhuangzi_ch-1","order":21,"canonicalText":"連叔曰：「然。」瞽者無以與乎文章之觀，聾者無以與乎鍾鼓之聲。豈唯形骸有聾瞽哉？夫知亦有之。是其言也，猶時女也。之人也，之德也，將旁礴萬物以為一，","sentenceIds":["zhuangzi_ch-1_p-21_s-1","zhuangzi_ch-1_p-21_s-2","zhuangzi_ch-1_p-21_s-3","zhuangzi_ch-1_p-21_s-4","zhuangzi_ch-1_p-21_s-5","zhuangzi_ch-1_p-21_s-6"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"連叔聽了感嘆道：「是啊！雙目失明的盲人，無法分享錦繡彩章的華美景觀；雙耳失聰的聾人，無法分享洪鐘靈鼓的和諧樂聲。難道只有肉體身軀才有耳聾眼瞎嗎？人的才智認知其實也是有盲目與聾聵的啊！這番話，正是說給你這樣的人聽的呢！那位神人啊，他的盛德與境界，將把紛繁複雜的萬事萬物混同融合為一體，","analysis":"【主旨】連叔以盲聾為喻，指出形體之盲聾尚在其次，認知心靈之「智之聾瞽」尤為可悲；進而揭示神人「旁礴萬物以為一」的齊物萬物一體論。\\n【詞義】「文章」古代青紅相間的彩色花紋；「形骸」肉體軀殼；「知亦有之」智慧認知亦有蔽塞無知之境；「猶時女也」正是說當下的你，「時」通「是」，「女」同「汝」；「旁礴」混同、包容、融貫；「以為一」齊合為整體。\\n【章法】以連叔一聲感嘆「然」直下棒喝，由感官生理缺陷類推到智性認知的殘缺，隨即將批判矛頭直指肩吾，筆鋒犀利老辣。\\n【思想】此處觸及認識論的最高深度：人類往往因為自身理性知性的局限，將看不見、聽不懂的更高境界斥為狂妄。神人之德不在於炫耀異能，而在於破除分別心，與宇宙萬物化而為一。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-22","chapterId":"zhuangzi_ch-1","order":22,"canonicalText":"世蘄乎亂，孰弊弊焉以天下為事！之人也，物莫之傷，大浸稽天而不溺，大旱金石流土山焦而不熱。是其塵垢粃穅，將猶陶鑄堯舜者也，孰肯以物為事！","sentenceIds":["zhuangzi_ch-1_p-22_s-1","zhuangzi_ch-1_p-22_s-2","zhuangzi_ch-1_p-22_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"世人縱然渴望動亂中求治，神人又哪裡肯汲汲營營、疲憊勞頓地把治理天下當作自己的事務呢！這樣的人啊，世間萬物沒有任何東西能傷害到他，滔天的滔天洪水即使漫天而上也不能將他淹沒，酷烈的特大旱災即使把金石熔化、土山烤焦也不能讓他感到酷熱。他身上散落的一點微末塵埃與粗糠粃秕，就足以陶冶塑造出唐堯虞舜那樣的聖王，他又哪裡肯把世俗外物當作自己畢生的事業呢！","analysis":"【主旨】論述神人精神超脫於水火生死之自然災害，其德之餘緒足以陶鑄堯舜，反思世人沈溺政治經世之勞形碌碌。\\n【詞義】「蘄」祈求、渴望；「弊弊焉」疲憊勞碌、汲汲營營貌；「大浸稽天」大水滔天漫延；「金石流」極端酷熱使金屬石頭融化流淌；「粃穅」粗糠粃秕，喻微不足道之餘屑；「陶鑄」燒瓦冶鐵，引申為塑造培養；「以物為事」受外物所奴役牽絆。\\n【章法】運用排山倒海的誇張修辭（「大浸稽天不溺」「金石流不熱」），以水火不侵彰顯心靈本體的絕對自由；再以「塵垢粃穅陶鑄堯舜」形成強烈價值顛覆，文氣極為震撼。\\n【思想】莊子並非主張逃避現實責任，而是揭示當人過度執迷於世俗權力事務（「以物為事」）時，必然喪失本真生命。精神超脫之人已超越物理與政治之羈絆，其自足性遠高於世俗帝王。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-23","chapterId":"zhuangzi_ch-1","order":23,"canonicalText":"「宋人資章甫而適諸越，越人斷髮文身，無所用之。堯治天下之民，平海內之政，往見四子藐姑射之山，汾水之陽，窅然喪其天下焉。」","sentenceIds":["zhuangzi_ch-1_p-23_s-1","zhuangzi_ch-1_p-23_s-2","zhuangzi_ch-1_p-23_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"「宋國有人販賣周代貴族戴的禮帽『章甫』到越國去，可是越國人習慣剪短頭髮、身刺花紋，根本用不著這種帽子。唐堯治理好了全天下的黎民百姓，整頓平定了四海九州的政務，千里迢迢前往藐姑射山、汾水北岸去拜見四位得道的大師，在那超然悠遠的境界中，悵然若失地忘掉了自己所擁有的整個天下。」","analysis":"【主旨】引宋人販冠越國之諷喻，指出世俗禮教制度之相對性與無用；並以堯見四子而「喪其天下」，為神人寓言作結，確立大道超越政治體系之崇高。\\n【詞義】「資」販賣、販運；「章甫」殷商流傳之貴族禮帽；「適」前往；「斷髮文身」古代越人剪髮刺身之水鄉習俗；「四子」藐姑射山四位得道隱士；「汾水之陽」汾水北面（山南水北為陽）；「窅然」深遠深邃、若有所失貌；「喪其天下」忘卻、放下了天下的所有與執念。\\n【章法】前設宋人販冠越國之滑稽設喻，後結聖王唐堯放下天下之肅穆神妙，一諧一莊，相映成趣，將世俗最高成就者（堯）的最終歸宿指向精神之解脫。\\n【思想】「章甫」象徵中原文明自矜的禮樂制度，在越人之地毫無價值，說明任何文化制度皆具相對性。而貴為天子的唐堯在見識大道之後，毅然放下對權力帝國的執著，正是「聖人無名、神人無功」的歷史顯現。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-24","chapterId":"zhuangzi_ch-1","order":24,"canonicalText":"惠子謂莊子曰：「魏王貽我大瓠之種，我樹之成而實五石，以盛水漿，其堅不能自舉也。剖之以為瓢，則瓠落無所容。非不呺然大也，吾為其無用而掊之。」","sentenceIds":["zhuangzi_ch-1_p-24_s-1","zhuangzi_ch-1_p-24_s-2","zhuangzi_ch-1_p-24_s-3","zhuangzi_ch-1_p-24_s-4"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"惠施對莊子說道：「魏惠王贈送給我一顆大葫蘆的種子，我將它栽種培育成熟，結出的葫蘆足足有五石的巨大容量。用它來盛裝水或漿汁，它的堅硬程度卻承載不起水的分量而容易破裂；如果把它切開剖成舀水的大瓢，它又過於寬大平淺，沒有任何器皿能容納得下它。它並非不高大空闊，然而我因為它毫無用處，就把它給砸碎打破了。」","analysis":"【主旨】莊惠對話第一幕：惠施以「大瓠無用而掊之」設喻，譏諷莊子的言論看似宏大宏闊，實則脫離實際、全無用處。\\n【詞義】「惠子」名惠施，戰國名家代表人物，莊子之至交與論辯對手；「貽」贈送；「大瓠」大葫蘆；「五石」古代重量或容量單位，一石約百二十斤，五石容量極大；「不能自舉」承受不了自身重量；「瓠落」平淺寬大貌；「呺然」龐大空洞貌；「掊」擊碎、砸碎。\\n【章法】惠施發難，先敘大瓠之來歷與培育之功，再細述作容器與作水瓢兩方面的失敗，最後以「為其無用而掊之」作結，言辭鋒利，邏輯步步緊逼。\\n【思想】惠施代表戰國功利主義與實用主義思維：一物之價值完全取決於其既定工具性功能（盛水、作瓢）。一旦無法迎合常規實用標準，便被斥為「無用」而遭棄毀。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-25","chapterId":"zhuangzi_ch-1","order":25,"canonicalText":"莊子曰：「夫子固拙於用大矣。宋人有善為不龜手之藥者，世世以洴澼絖為事。客聞之，請買其方百金。","sentenceIds":["zhuangzi_ch-1_p-25_s-1","zhuangzi_ch-1_p-25_s-2","zhuangzi_ch-1_p-25_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"莊子回答說：「先生您真是不擅長運用龐大的事物啊！宋國有一戶人家，擅長調配製造預防冬天手腳皮膚凍裂的特效藥膏，世世代代都以在水中漂洗絲絮為職業。有一個外鄉旅客聽說了這件事，願意出百金的高昂代價請求購買他們的藥方。","analysis":"【主旨】莊惠對話第二幕：莊子直斥惠施「拙於用大」，並以宋人世代「不龜手之藥」寓言開端，破除實用主義對事物價值的窄化理解。\\n【詞義】「固」確實、本來；「拙於用大」不善於在更大格局中運用宏大事物；「不龜手」手皮膚不凍裂，「龜」音軍，同皸，手足凍裂紋理；「洴澼絖」在水中漂洗絲綿絮，洴澼為漂洗，絖為絲綿細絮；「客」過路旅客、外鄉人；「百金」極大之重金。\\n【章法】首句「夫子固拙於用大矣」單刀直入反駁，隨即導入生活化之宋人寓言，以世世代代漂洗絲絮之卑微生計，對照外客百金求方之巨款，製造強烈的戲劇懸念。\\n【思想】事物的價值並非固定不變，關鍵在於主體能否突破思維定勢，將潛在資源轉移至更高維度加以運用。宋人之「善為藥」受限於固有生活經驗，無法自覺其巨大潛力。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-26","chapterId":"zhuangzi_ch-1","order":26,"canonicalText":"聚族而謀曰：「『我世世為洴澼絖，不過數金；今一朝而鬻技百金，請與之。』客得之，以說吳王。越有難，吳王使之將，","sentenceIds":["zhuangzi_ch-1_p-26_s-1","zhuangzi_ch-1_p-26_s-2","zhuangzi_ch-1_p-26_s-3","zhuangzi_ch-1_p-26_s-4"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"這家人聚集全家族的人商量道：『我們世世代代替人漂洗絲絮，所得報酬不過幾兩銀子；如今一旦賣出這門技術就能獲取百金暴利，請同意把藥方賣給他吧！』外客得到了這張藥方，便前往遊說吳王。恰逢越國發兵侵犯吳國，吳王便派這位外客統率軍隊擔任大將，","analysis":"【主旨】宋人以微薄小利賣出祖傳良方，外客則將藥方轉化為重大軍事戰略資產，鮮明展現認知視野差異所導致的命運落差。\\n【詞義】「鬻技」出賣技術專長；「難」軍事犯難、戰亂；「將」統帥將領，此作動詞任大將。\\n【章法】記敘宋人宗族會議之心理，以「世世不過數金」與「一朝百金」對比，逼真勾勒出小生產者的自滿侷限；緊接著筆鋒一轉，外客迅速將藥方推向吳越地緣政治之爭，節奏明快。\\n【思想】同一技術，宋人視為漂洗絲絮之微末小技，外客卻洞察其在冬季水戰中的決定性戰術價值。這表明認知的層次直接決定了資源轉化的維度。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-27","chapterId":"zhuangzi_ch-1","order":27,"canonicalText":"冬與越人水戰，大敗越人，裂地而封之。能不龜手，一也；或以封，或不免於洴澼絖，則所用之異也。","sentenceIds":["zhuangzi_ch-1_p-27_s-1","zhuangzi_ch-1_p-27_s-2","zhuangzi_ch-1_p-27_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"寒冬臘月時與越國軍隊進行水戰，把越國打得大敗，吳王因此劃分土地封賞給他。同樣是一張能讓手腳不凍裂的藥方，有的人憑藉它獲得了裂土封侯的大賞，有的人卻始終免不了在嚴冬冰水裡漂洗絲絮的勞苦，這就是使用方式與器局格局的不同所造成的啊！","analysis":"【主旨】總結不龜手之藥寓言：同一事物，因使用者格局境界與運用方式之異，其成效與命運有天壤之別。\\n【詞義】「裂地而封」割裂領土封為諸侯卿大夫；「一也」本質是同一個東西；「所用之異」運用途徑、認知格局之差異。\\n【章法】在水戰大勝之事實後，莊子以簡短警策之語作對比提煉：「或以封，或不免於洴澼絖，則所用之異也」，如論綱收束，發人深省。\\n【思想】「所用之異」是莊子實踐哲學的重大命題。世人往往抱怨生不逢時或資源匱乏，莊子卻指出真正的貧困在於心靈格局的狹窄，無法發現事物在超越常規語境下的無窮妙用。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-28","chapterId":"zhuangzi_ch-1","order":28,"canonicalText":"今子有五石之瓠，何不慮以為大樽而浮乎江湖，而憂其瓠落無所容？則夫子猶有蓬之心也夫！」","sentenceIds":["zhuangzi_ch-1_p-28_s-1","zhuangzi_ch-1_p-28_s-2","zhuangzi_ch-1_p-28_s-3"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如今您擁有這能盛五石的大葫蘆，為什麼不考慮把它繫在腰間當作漂浮的救生大腰舟，逍遙自在地浮游於遼闊的江河湖海之上，反而整天發愁它太過平淺寬大而沒有器皿能容納得下呢？看來先生您的心靈，還是像雜草叢生的蓬蒿一樣茅塞閉塞啊！」","analysis":"【主旨】莊惠對話收束：莊子將大瓠從盛水之器皿轉化為浮游江湖之「大樽」，以此批判惠施實用功利心靈的閉塞狹隘（「蓬之心」）。\\n【詞義】「慮」結縛、籌劃；「大樽」古代用以綁在腰間助人浮水之腰舟、葫蘆浮具；「江湖」江河湖泊，亦喻精神廣闊自由之天地；「蓬之心」心如蓬草雜亂閉塞、見識淺陋不通。\\n【章法】從宋人之藥急轉回惠子之大瓠，以「浮乎江湖」對照「瓠落無所容」，氣象頓開；末句「夫子猶有蓬之心也夫」如當頭棒喝，收結全段。\\n【思想】打破把事物局限在實用容器（名位、世俗成就）的觀念。大瓠正因為「無用」於盛水，才能成為遨遊江湖的精神方舟。真正的自由在於徹底打破常規價值尺度。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-29","chapterId":"zhuangzi_ch-1","order":29,"canonicalText":"惠子謂莊子曰：「吾有大樹，人謂之樗。其大本擁腫而不中繩墨，其小枝捲曲而不中規矩，立之塗，匠者不顧。今子之言，大而無用，眾所同去也。」","sentenceIds":["zhuangzi_ch-1_p-29_s-1","zhuangzi_ch-1_p-29_s-2","zhuangzi_ch-1_p-29_s-3","zhuangzi_ch-1_p-29_s-4"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"惠施又對莊子說道：「我有一棵巨大的樹，人們稱它為『樗樹』。它的樹幹盤根錯節、長滿贅瘤而不符合木匠劃直線的繩墨，它的小枝彎彎曲曲而不符合木匠畫圓方的規矩。即便將它生長在熱鬧的道路旁，過往的木匠工匠也連看都不會看它一眼。如今先生您的言論，廣大而毫無用處，正是天下眾人所共同唾棄遺棄的啊！」","analysis":"【主旨】莊惠對話第三幕：惠施再舉大樗之樹為喻，指責其不成材、不中繩墨，藉此再度猛烈抨擊莊子之學說「大而無用，眾所同去」。\\n【詞義】「樗」臭椿樹，木質疏鬆多瘤；「大本」大樹幹、主幹；「擁腫」木質粗大彎曲多贅瘤結節；「中」合乎；「繩墨」木匠取直的墨斗墨線；「規矩」畫圓畫方的工具；「塗」通途，道路；「去」拋棄、唾棄。\\n【章法】惠施以生動之細節連下三處缺陷：「大本擁腫不中繩墨」「小枝捲曲不中規矩」「匠者不顧」，語氣凌厲，隨即將批判由「物」直引至莊子之「言」，形成強烈挑戰。\\n【思想】惠施代表標準的儒墨工匠社會標準：一切必須符合「繩墨規矩」之禮法功利尺度。凡不能被社會制度切割利用、納入實用體系的生命與思想，皆被判定為不合格之廢物。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-30","chapterId":"zhuangzi_ch-1","order":30,"canonicalText":"莊子曰：「子獨不見狸狌乎？卑身而伏，以候敖者；東西跳梁，不避高下；中於機闢，死於罔罟。","sentenceIds":["zhuangzi_ch-1_p-30_s-1","zhuangzi_ch-1_p-30_s-2","zhuangzi_ch-1_p-30_s-3","zhuangzi_ch-1_p-30_s-4"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"莊子回答道：「先生您難道沒見過野貓與黃鼠狼嗎？它們把身子低低地趴在地上，專門窺伺等候那些出來遊蕩遊玩的小動物；東跳西躍、矯捷機靈，不避開高處與低處；然而往往觸碰到捕獸機關的機栝，最終慘死在獵人的羅網陷阱之中。","analysis":"【主旨】莊惠對話第四幕：莊子以「狸狌之死」為喻，揭示汲汲於展現實用小聰明、敏捷捕食之人，往往反受機巧所害，招致殺身之禍。\\n【詞義】「狸狌」野貓與黃鼠狼之類捕鼠獸；「敖者」敖同遨，遊逛出遊之鳥雀小獸；「跳梁」騰躍跳動；「機闢」捕獸之機關陷阱；「罔罟」罔同網，罟為捕獸魚網。\\n【章法】莊子不直接辯解樗樹之價值，而是反客為主，先描繪以敏捷實用著稱之狸狌「卑身跳梁」之得意態，旋即以「死於罔罟」急轉直下，展現深刻的辯證危機。\\n【思想】世人常為具備「有用」之才藝自喜（如官員之於政術、士人之於辭章），莊子卻清醒指出：機巧正是殺身之階梯。過度炫耀實用之能，往往促使其陷入名利權力的絞肉機中而喪失生命。","historicalContext":"","keywords":[]}},{"id":"zhuangzi_ch-1_p-31","chapterId":"zhuangzi_ch-1","order":31,"canonicalText":"今夫斄牛，其大若垂天之雲。此能為大矣，而不能執鼠。今子有大樹，患其無用，何不樹之於無何有之鄉，廣莫之野，彷徨乎無為其側，逍遙乎寢臥其下。不夭斤斧，物無害者，無所可用，安所困苦哉！」","sentenceIds":["zhuangzi_ch-1_p-31_s-1","zhuangzi_ch-1_p-31_s-2","zhuangzi_ch-1_p-31_s-3","zhuangzi_ch-1_p-31_s-4","zhuangzi_ch-1_p-31_s-5"],"sourceRefs":[{"label":"《莊子》—中國哲學書電子化計劃","edition":"郭慶藩《莊子集釋》本","location":"https://ctext.org/zhuangzi/zh","accessedAt":"2026-08-31"},{"label":"《莊子》—維基文庫","edition":"郭象注・成玄英疏《莊子註疏》","location":"https://zh.wikisource.org/zh-hant/莊子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"再看看那西域的氂牛，它的身軀龐大得就像天邊垂落的雲彩。這確實稱得上龐大了，然而它卻連一隻小老鼠都捉不到。如今您有一棵這樣巨大的樹，卻天天發愁它毫無用處，為什麼不乾脆把它栽種在空寂寧靜的『無何有之鄉』、無邊無際的『廣莫之野』呢？在它的身旁悠閒自在地安享無為，在它的樹蔭下無牽無掛地逍遙寢臥。它不會遭到斧斤利刃的夭折砍伐，世間也沒有任何東西會去傷害摧殘它。正因為它沒有任何常規的世俗用途，它又哪裡會有什麼困厄與苦惱呢！」","analysis":"【主旨】〈逍遙遊〉全篇終極收束：以「無用之大用」化解惠施之執念，提出「無何有之鄉，廣莫之野」的精神原鄉，為心靈找到絕對免除傷害、逍遙安歇的終極歸宿。\\n【詞義】「斄牛」氂牛，體型巨大；「執鼠」捕抓老鼠；「樹」種植、栽植；「無何有之鄉」一無所有的純真廣大虛靜之境；「廣莫之野」廣袤無邊之曠野；「彷徨」自得徘徊沈浸貌；「逍遙」無拘無束、自由自在；「夭」摧折夭折；「斤斧」伐木斧頭；「安所困苦」哪裡會有困苦。\\n【章法】由氂牛「能為大而不能執鼠」反駁單一實用標準，隨即以如詩如畫的超凡筆墨構建出「無何有之鄉」「廣莫之野」，並以連續四字句「彷徨無為」「逍遙寢臥」「不夭斤斧」「物無害者」層層推進，最後以「無所可用，安所困苦哉」之反問傲然作結，迴腸盪氣。\\n【思想】這是全篇思想的最深底牌。「有用」使萬物淪為工具、遭受砍伐剖削；唯有看清「無用」，方能保全真性，達到「不夭斤斧、物無害之」的大安寧。莊子以這棵超然於功利之外的大樗樹，矗立在人類精神史的廣莫之野，庇護著每一個尋求心靈絕對自由的靈魂。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"zhuangzi_ch-1_p-1_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-1","order":1,"canonicalText":"北冥有魚，其名為鯤。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-1_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-1","order":2,"canonicalText":"鯤之大，不知其幾千里也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-1_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-1","order":3,"canonicalText":"化而為鳥，其名為鵬。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-1_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-1","order":4,"canonicalText":"鵬之背，不知其幾千里也；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-1_s-5","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-1","order":5,"canonicalText":"怒而飛，其翼若垂天之雲。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-1_s-6","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-1","order":6,"canonicalText":"是鳥也，海運則將徙於南冥。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-1_s-7","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-1","order":7,"canonicalText":"南冥者，天池也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-2_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-2","order":1,"canonicalText":"齊諧者，志怪者也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-2_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-2","order":2,"canonicalText":"曰：「鵬之徙於南冥也，水擊三千里，摶扶搖而上者九萬裏，去以六月息者也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-2_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-2","order":3,"canonicalText":"」野馬也，塵埃也，生物之以息相吹也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-3_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-3","order":1,"canonicalText":"天之蒼蒼，其正色邪？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-3_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-3","order":2,"canonicalText":"其遠而無所至極邪？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-3_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-3","order":3,"canonicalText":"其視下也，亦若是則已矣。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-4_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-4","order":1,"canonicalText":"且夫水之積也不厚，則負大舟也無力。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-4_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-4","order":2,"canonicalText":"覆杯水於坳堂之上，則芥為之舟；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-4_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-4","order":3,"canonicalText":"置杯焉則膠，水淺而舟大也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-4_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-4","order":4,"canonicalText":"風之積也不厚，則其負大翼也無力。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-4_s-5","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-4","order":5,"canonicalText":"故九萬裏，則風斯在下矣，而後乃今培風；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-4_s-6","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-4","order":6,"canonicalText":"背負青天，而莫之夭閼者，而後乃今將圖南。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-5_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-5","order":1,"canonicalText":"蜩與學鳩笑之曰：「我決起而飛，槍榆枋，時則不至，而控於地而已矣，奚以之九萬裏而南為？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-5_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-5","order":2,"canonicalText":"」適莽蒼者，三湌而反，腹猶果然；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-5_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-5","order":3,"canonicalText":"適百里者，宿舂糧；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-5_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-5","order":4,"canonicalText":"適千里者，三月聚糧。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-5_s-5","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-5","order":5,"canonicalText":"之二蟲又何知！","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-6_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-6","order":1,"canonicalText":"小知不及大知，小年不及大年。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-6_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-6","order":2,"canonicalText":"奚以知其然也？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-6_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-6","order":3,"canonicalText":"朝菌不知晦朔，蟪蛄不知春秋，此小年也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-7_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-7","order":1,"canonicalText":"楚之南有冥靈者，以五百歲為春，五百歲為秋；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-7_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-7","order":2,"canonicalText":"上古有大椿者，以八千歲為春，八千歲為秋。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-7_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-7","order":3,"canonicalText":"而彭祖乃今以久特聞，眾人匹之，不亦悲乎！","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-8_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-8","order":1,"canonicalText":"湯之問棘也是已。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-8_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-8","order":2,"canonicalText":"窮髮之北有冥海者，天池也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-8_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-8","order":3,"canonicalText":"有魚焉，其廣數千里，未有知其脩者，其名為鯤。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-8_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-8","order":4,"canonicalText":"有鳥焉，其名為鵬，背若泰山，翼若垂天之雲，","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-9_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-9","order":1,"canonicalText":"摶扶搖羊角而上者九萬裏，絕雲氣，負青天，然後圖南，且適南冥也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-10_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-10","order":1,"canonicalText":"斥鴳笑之曰：「彼且奚適也？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-10_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-10","order":2,"canonicalText":"我騰躍而上，不過數仞而下，翱翔蓬蒿之間，此亦飛之至也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-10_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-10","order":3,"canonicalText":"而彼且奚適也？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-10_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-10","order":4,"canonicalText":"」此小大之辯也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-11_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-11","order":1,"canonicalText":"故夫知效一官，行比一鄉，德合一君，而徵一國者，其自視也亦若此矣。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-11_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-11","order":2,"canonicalText":"而宋榮子猶然笑之。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-11_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-11","order":3,"canonicalText":"且舉世而譽之而不加勸，舉世而非之而不加沮，","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-12_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-12","order":1,"canonicalText":"定乎內外之分，辯乎榮辱之竟斯已矣。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-12_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-12","order":2,"canonicalText":"彼其於世未數數然也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-12_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-12","order":3,"canonicalText":"雖然，猶有未樹也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-12_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-12","order":4,"canonicalText":"夫列子御風而行，泠然善也，旬有五日而後反。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-13_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-13","order":1,"canonicalText":"彼於致福者，未數數然也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-13_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-13","order":2,"canonicalText":"此雖免乎行，猶有所待者也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-13_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-13","order":3,"canonicalText":"若夫乘天地之正，而御六氣之辯，以遊無窮者，彼且惡乎待哉！","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-13_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-13","order":4,"canonicalText":"故曰：至人無己，神人無功，聖人無名。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-14_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-14","order":1,"canonicalText":"堯讓天下於許由，曰：「日月出矣，而爝火不息，其於光也，不亦難乎！","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-14_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-14","order":2,"canonicalText":"時雨降矣，而猶浸灌，其於澤也，不亦勞乎！","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-15_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-15","order":1,"canonicalText":"夫子立而天下治，而我猶屍之，吾自視缺然。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-15_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-15","order":2,"canonicalText":"請致天下。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-15_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-15","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-16_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-16","order":1,"canonicalText":"許由曰：「子治天下，天下既已治也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-16_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-16","order":2,"canonicalText":"而我猶代子，吾將為名乎？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-16_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-16","order":3,"canonicalText":"名者，實之賓也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-16_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-16","order":4,"canonicalText":"吾將為賓乎？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-17_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-17","order":1,"canonicalText":"鷦鷯巢於深林，不過一枝；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-17_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-17","order":2,"canonicalText":"偃鼠飲河，不過滿腹。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-17_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-17","order":3,"canonicalText":"歸休乎君，予無所用天下為！","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-17_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-17","order":4,"canonicalText":"庖人雖不治庖，尸祝不越樽俎而代之矣。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-17_s-5","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-17","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-18_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-18","order":1,"canonicalText":"肩吾問於連叔曰：「吾聞言於接輿，大而無當，往而不反。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-18_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-18","order":2,"canonicalText":"吾驚怖其言，猶河漢而無極也；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-18_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-18","order":3,"canonicalText":"大有逕庭，不近人情焉。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-18_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-18","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-19_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-19","order":1,"canonicalText":"連叔曰：「其言謂何哉？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-19_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-19","order":2,"canonicalText":"」","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-20_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-20","order":1,"canonicalText":"曰：「藐姑射之山，有神人居焉，肌膚若冰雪，淖約若處子。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-20_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-20","order":2,"canonicalText":"不食五穀，吸風飲露。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-20_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-20","order":3,"canonicalText":"乘雲氣，御飛龍，而遊乎四海之外。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-20_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-20","order":4,"canonicalText":"其神凝，使物不疵癘而年穀熟，吾以是狂而不信也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-20_s-5","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-20","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-21_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-21","order":1,"canonicalText":"連叔曰：「然。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-21_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-21","order":2,"canonicalText":"」瞽者無以與乎文章之觀，聾者無以與乎鍾鼓之聲。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-21_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-21","order":3,"canonicalText":"豈唯形骸有聾瞽哉？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-21_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-21","order":4,"canonicalText":"夫知亦有之。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-21_s-5","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-21","order":5,"canonicalText":"是其言也，猶時女也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-21_s-6","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-21","order":6,"canonicalText":"之人也，之德也，將旁礴萬物以為一，","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-22_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-22","order":1,"canonicalText":"世蘄乎亂，孰弊弊焉以天下為事！","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-22_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-22","order":2,"canonicalText":"之人也，物莫之傷，大浸稽天而不溺，大旱金石流土山焦而不熱。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-22_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-22","order":3,"canonicalText":"是其塵垢粃穅，將猶陶鑄堯舜者也，孰肯以物為事！","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-23_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-23","order":1,"canonicalText":"「宋人資章甫而適諸越，越人斷髮文身，無所用之。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-23_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-23","order":2,"canonicalText":"堯治天下之民，平海內之政，往見四子藐姑射之山，汾水之陽，窅然喪其天下焉。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-23_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-23","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-24_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-24","order":1,"canonicalText":"惠子謂莊子曰：「魏王貽我大瓠之種，我樹之成而實五石，以盛水漿，其堅不能自舉也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-24_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-24","order":2,"canonicalText":"剖之以為瓢，則瓠落無所容。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-24_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-24","order":3,"canonicalText":"非不呺然大也，吾為其無用而掊之。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-24_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-24","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-25_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-25","order":1,"canonicalText":"莊子曰：「夫子固拙於用大矣。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-25_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-25","order":2,"canonicalText":"宋人有善為不龜手之藥者，世世以洴澼絖為事。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-25_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-25","order":3,"canonicalText":"客聞之，請買其方百金。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-26_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-26","order":1,"canonicalText":"聚族而謀曰：「『我世世為洴澼絖，不過數金；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-26_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-26","order":2,"canonicalText":"今一朝而鬻技百金，請與之。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-26_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-26","order":3,"canonicalText":"』客得之，以說吳王。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-26_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-26","order":4,"canonicalText":"越有難，吳王使之將，","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-27_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-27","order":1,"canonicalText":"冬與越人水戰，大敗越人，裂地而封之。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-27_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-27","order":2,"canonicalText":"能不龜手，一也；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-27_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-27","order":3,"canonicalText":"或以封，或不免於洴澼絖，則所用之異也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-28_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-28","order":1,"canonicalText":"今子有五石之瓠，何不慮以為大樽而浮乎江湖，而憂其瓠落無所容？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-28_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-28","order":2,"canonicalText":"則夫子猶有蓬之心也夫！","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-28_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-28","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-29_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-29","order":1,"canonicalText":"惠子謂莊子曰：「吾有大樹，人謂之樗。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-29_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-29","order":2,"canonicalText":"其大本擁腫而不中繩墨，其小枝捲曲而不中規矩，立之塗，匠者不顧。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-29_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-29","order":3,"canonicalText":"今子之言，大而無用，眾所同去也。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-29_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-29","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-30_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-30","order":1,"canonicalText":"莊子曰：「子獨不見狸狌乎？","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-30_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-30","order":2,"canonicalText":"卑身而伏，以候敖者；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-30_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-30","order":3,"canonicalText":"東西跳梁，不避高下；","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-30_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-30","order":4,"canonicalText":"中於機闢，死於罔罟。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-31_s-1","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-31","order":1,"canonicalText":"今夫斄牛，其大若垂天之雲。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-31_s-2","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-31","order":2,"canonicalText":"此能為大矣，而不能執鼠。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-31_s-3","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-31","order":3,"canonicalText":"今子有大樹，患其無用，何不樹之於無何有之鄉，廣莫之野，彷徨乎無為其側，逍遙乎寢臥其下。","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-31_s-4","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-31","order":4,"canonicalText":"不夭斤斧，物無害者，無所可用，安所困苦哉！","chunks":[],"tags":[]},{"id":"zhuangzi_ch-1_p-31_s-5","workId":"zhuangzi","chapterId":"zhuangzi_ch-1","passageId":"zhuangzi_ch-1_p-31","order":5,"canonicalText":"」","chunks":[],"tags":[]}]}');export{a as default};
